  assert.match(exactResult.body.toString('utf8'), /"id"/);

  const over = paddedProductJson(pad + 1);
  assert.equal(over.length, MAX_BODY_BYTES + 1);
  assertTooLargeResponse(await postRawWithLength(server.url, over));
});

